local ClothPresserMaker = {}
local PRODUCTS = {
    iron_cloth_presser = { name = "Železno stiskalec tkinin", ironCost = 4, woodCost = 2, leatherCost = 1, time = 5, cost = 180, prestige = 4, happiness = 2, description = "Železno stiskalec za glajenje tkinin." },
    bronze_cloth_presser = { name = "Bronasto stiskalec tkinin", bronzeCost = 4, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 435, prestige = 6, happiness = 3, description = "Bronasto stiskalec za fino glajenje." },
    silver_cloth_presser = { name = "Srebrno stiskalec tkinin", silverCost = 4, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 1050, prestige = 11, happiness = 4, description = "Srebrno stiskalec za plemiške tkače." },
    gilded_cloth_presser = { name = "Pozlačeno stiskalec tkinin", goldCost = 1, silverCost = 4, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 2250, prestige = 20, happiness = 5, description = "Pozlačeno stiskalec za dvorne tkače." },
    jewel_set_cloth_presser = { name = "Draguljasto stiskalec tkinin", goldCost = 2, silverCost = 4, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4850, prestige = 36, happiness = 7, description = "Draguljasto stiskalec za kraljevske tkače." },
    royal_sovereign_cloth_presser = { name = "Kraljevski suvereno stiskalec tkinin", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 10400, prestige = 69, happiness = 13, description = "Suvereno stiskalec z biseri za krono." },
}
local BUILDINGS = {
    clothpresser_workshop = { name = "Stiskalna delavnica", cost = { gold = 365, wood = 180, stone = 140, iron = 9 }, upkeep = 7, qualityBonus = 5 },
    clothpresser_house = { name = "Stiskalna hiša", cost = { gold = 1285, wood = 365, stone = 285, silver = 8, iron = 8 }, upkeep = 27, qualityBonus = 18 },
    master_clothpresser_atelier = { name = "Mojstrski stiskalni atelje", cost = { gold = 3200, wood = 425, stone = 540, silver = 39, gold = 8 }, upkeep = 75, qualityBonus = 30 },
    sovereign_clothpresser_palace = { name = "Suverena stiskalna palača", cost = { gold = 13600, wood = 655, stone = 860, gold = 88, jewel = 20 }, upkeep = 263, qualityBonus = 55, prestigeBonus = 50 },
}
ClothPresserMaker.ironStock = 16; ClothPresserMaker.bronzeStock = 14; ClothPresserMaker.woodStock = 12; ClothPresserMaker.leatherStock = 10; ClothPresserMaker.silverStock = 8; ClothPresserMaker.goldStock = 6; ClothPresserMaker.jewelStock = 4; ClothPresserMaker.pearlStock = 4
ClothPresserMaker.productStock = {}; ClothPresserMaker.buildings = {}; ClothPresserMaker.maker = nil; ClothPresserMaker.activeMaking = {}; ClothPresserMaker.totalProducts = 0; ClothPresserMaker.dayTimer = 0
function ClothPresserMaker.init() ClothPresserMaker.ironStock=16; ClothPresserMaker.bronzeStock=14; ClothPresserMaker.woodStock=12; ClothPresserMaker.leatherStock=10; ClothPresserMaker.silverStock=8; ClothPresserMaker.goldStock=6; ClothPresserMaker.jewelStock=4; ClothPresserMaker.pearlStock=4; ClothPresserMaker.productStock={}; ClothPresserMaker.buildings={}; ClothPresserMaker.maker=nil; ClothPresserMaker.activeMaking={}; ClothPresserMaker.totalProducts=0; ClothPresserMaker.dayTimer=0; print("[ClothPresserMaker] Royal Cloth Presser Maker System initialized (6 products, 4 buildings)") end
function ClothPresserMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ClothPresserMaker.maker={name=n or ("Stiskalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stiskalec najet: %s (spretnost: %d)",ClothPresserMaker.maker.name,s),"success") end; return true end
function ClothPresserMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ClothPresserMaker.build(id) local ok,e=ClothPresserMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ClothPresserMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ClothPresserMaker.getQualityBonus() local b=0; for _,bd in ipairs(ClothPresserMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ClothPresserMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ClothPresserMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ClothPresserMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ClothPresserMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ClothPresserMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ClothPresserMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ClothPresserMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ClothPresserMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ClothPresserMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ClothPresserMaker.buildings==0 then return false,"Potrebna stiskalna delavnica" end; if not ClothPresserMaker.maker then return false,"Potreben stiskalec" end; return true end
function ClothPresserMaker.make(pt,qty) qty=qty or 1; local ok,e=ClothPresserMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ClothPresserMaker.ironStock=ClothPresserMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ClothPresserMaker.bronzeStock=ClothPresserMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ClothPresserMaker.woodStock=ClothPresserMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ClothPresserMaker.leatherStock=ClothPresserMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ClothPresserMaker.silverStock=ClothPresserMaker.silverStock-d.silverCost*qty end; if d.goldCost then ClothPresserMaker.goldStock=ClothPresserMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ClothPresserMaker.jewelStock=ClothPresserMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ClothPresserMaker.pearlStock=ClothPresserMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ClothPresserMaker.maker then t=math.max(1,t-math.floor(ClothPresserMaker.maker.skill/13)) end; table.insert(ClothPresserMaker.activeMaking,{id="clothpresser_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ClothPresserMaker.completeMaking(m) local q=1.0+(ClothPresserMaker.getQualityBonus()/100); if ClothPresserMaker.maker then q=q+(ClothPresserMaker.maker.skill/140) end; q=math.min(2.5,q); ClothPresserMaker.productStock[m.productType]=(ClothPresserMaker.productStock[m.productType] or 0)+m.quantity; ClothPresserMaker.totalProducts=ClothPresserMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ClothPresserMaker.maker then ClothPresserMaker.maker.itemsMade=ClothPresserMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ClothPresserMaker.maker.skill=math.min(100,ClothPresserMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stiskalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"clothpresser.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ClothPresserMaker.update(dt) if not _G.state then return end; ClothPresserMaker.dayTimer=ClothPresserMaker.dayTimer+dt; if ClothPresserMaker.dayTimer>=30 then ClothPresserMaker.dayTimer=0; for i=#ClothPresserMaker.activeMaking,1,-1 do local m=ClothPresserMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ClothPresserMaker.completeMaking(m); table.remove(ClothPresserMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ClothPresserMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ClothPresserMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ClothPresserMaker.getStats() return {ironStock=ClothPresserMaker.ironStock,bronzeStock=ClothPresserMaker.bronzeStock,woodStock=ClothPresserMaker.woodStock,leatherStock=ClothPresserMaker.leatherStock,silverStock=ClothPresserMaker.silverStock,goldStock=ClothPresserMaker.goldStock,jewelStock=ClothPresserMaker.jewelStock,pearlStock=ClothPresserMaker.pearlStock,productStock=ClothPresserMaker.productStock,numBuildings=#ClothPresserMaker.buildings,hasMaker=ClothPresserMaker.maker~=nil,makerName=ClothPresserMaker.maker and ClothPresserMaker.maker.name or "—",makerSkill=ClothPresserMaker.maker and ClothPresserMaker.maker.skill or 0,activeMaking=#ClothPresserMaker.activeMaking,totalProducts=ClothPresserMaker.totalProducts} end
return ClothPresserMaker
